package com.interview.mysqlescdc.verifier.rebuild;
import static org.assertj.core.api.Assertions.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.datasource.DriverManagerDataSource;
class RebuildAdvisoryLockIT{@Test void dedicated_mysql_lock_rejects_second_process_and_releases_after_owner_finishes()throws Exception{var ds=new DriverManagerDataSource("jdbc:mysql://127.0.0.1:3308/product_catalog?useSSL=false&allowPublicKeyRetrieval=true","verifier","verifierpass");var first=new RebuildAdvisoryLock(ds);var second=new RebuildAdvisoryLock(ds);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var held=executor.submit(()->first.execute(()->{entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return "done";}));assertThat(entered.await(5,TimeUnit.SECONDS)).isTrue();assertThatThrownBy(()->second.execute(()->"impossible")).isInstanceOf(IllegalStateException.class).hasMessageContaining("busy");release.countDown();assertThat(held.get(5,TimeUnit.SECONDS)).isEqualTo("done");assertThat(second.execute(()->"acquired")).isEqualTo("acquired");}}}
